import { getCommandes } from "../services/serviceCommandes";

export default function MesCommandes() {
  const commandes = getCommandes();

  return (
    <div style={{ padding: "30px" }}>
      <h2>Mes Commandes</h2>
      {commandes.length === 0 ? <p>Aucune commande passée.</p> : commandes.map((cmd) => (
        <div key={cmd.id} style={{ backgroundColor: "white", borderRadius: "8px", padding: "16px", margin: "12px 0", boxShadow: "0 1px 4px rgba(0,0,0,0.1)" }}>
          <p><strong>Commande #{cmd.id}</strong> — {cmd.date}</p>
          <p>Total : <strong style={{ color: "#e44d26" }}>{cmd.total?.toFixed(2)} €</strong></p>
          <p>{cmd.articles?.length} article(s)</p>
        </div>
      ))}
    </div>
  );
}
